        while x % 2 == 0:
            factors.add(2)
            x //= 2
        # Check for other primes
        for i in range(3, int(x**0.5)+1, 2):
            while x % i == 0:
                factors.add(i)
                x //= i
        if x > 2:
            factors.add(x)
        return len(factors)

    # Initialize dp array
    dp = [0] * (1 << N)

    # Iterate over all subsets
    for mask in range(1, 1 << N):
        current_sum = 0
        for i in range(N):
            if mask & (1 << i):
                current_sum += S[i]
        dp[mask] = count_prime_factors(current_sum)

    # The answer is the maximum value in dp array
    return max(dp)

